func (c *Context) NegotiateFormat(offered ...string) string {
	if c.accepted == nil {
		c.accepted = parseAccept(c.Request.Header.Get("Accept"))
	}
	if len(c.accepted) == 0 {
		return offered[0]

	} else {
		for _, accepted := range c.accepted {
			for _, offert := range offered {
				if accepted == offert {
					return offert
				}
			}
		}
		return ""
	}
}

